const fs = require('fs/promises');
const path = require('path');
const env = require('../config/env');

// File storage behind three functions, so moving to S3/Cloudinary later means
// rewriting this file only. The database stores keys ("avatars/<uuid>.webp"), never
// URLs, and urlFor builds the URL at read time.
//
// Local driver: files live under UPLOAD_DIR and app.js serves them at /uploads.
// Keys are always generated by the server, never taken from a request.

const ROOT = path.resolve(env.UPLOAD_DIR);

const save = async (key, buffer) => {
    const file = path.join(ROOT, key);
    await fs.mkdir(path.dirname(file), { recursive: true });
    await fs.writeFile(file, buffer);
};

const remove = (key) => fs.rm(path.join(ROOT, key), { force: true });

const urlFor = (key) => (key ? `${env.publicBaseUrl}/uploads/${key}` : null);

module.exports = { ROOT, save, remove, urlFor };
